{"id":"7b31b241-2da9-4037-9660-b55000b04ce7","inserted_at":"2026-07-08T00:29:57.834952+00:00","updated_at":"2026-07-08T00:29:57.834952+00:00","type":"sql","name":"Untitled query","description":"","content":{"sql":"-- ==========================================\r\n-- RIPRISTINO COLONNE MANCANTI E RPC\r\n-- (Questo risolve la Home vuota che non riusciva a caricare le RPC)\r\n-- ==========================================\r\n\r\n-- 1. Aggiungiamo le colonne mancanti alla tabella pois (usate per l'interfaccia Home/Esplora)\r\nALTER TABLE public.pois\r\nADD COLUMN IF NOT EXISTS crowd_level INTEGER DEFAULT 20,\r\nADD COLUMN IF NOT EXISTS has_water BOOLEAN DEFAULT false,\r\nADD COLUMN IF NOT EXISTS alternative_poi_id UUID REFERENCES public.pois(id),\r\nADD COLUMN IF NOT EXISTS is_recommended BOOLEAN DEFAULT false,\r\nADD COLUMN IF NOT EXISTS p_iva TEXT,\r\nADD COLUMN IF NOT EXISTS image_url TEXT,\r\nADD COLUMN IF NOT EXISTS description TEXT;\r\n\r\n-- 2. Aggiorniamo get_pois()\r\nDROP FUNCTION IF EXISTS get_pois();\r\n\r\nCREATE OR REPLACE FUNCTION get_pois()\r\nRETURNS TABLE (\r\n    id UUID,\r\n    name TEXT,\r\n    category TEXT,\r\n    layer_name TEXT,\r\n    xp_reward INTEGER,\r\n    checkin_radius INTEGER,\r\n    crowd_level INTEGER,\r\n    has_water BOOLEAN,\r\n    is_accessible BOOLEAN,\r\n    alternative_poi_id UUID,\r\n    is_recommended BOOLEAN,\r\n    latitude FLOAT8,\r\n    longitude FLOAT8,\r\n    p_iva TEXT,\r\n    image_url TEXT,\r\n    description TEXT\r\n) AS $$\r\nBEGIN\r\n    RETURN QUERY\r\n    SELECT \r\n        p.id, \r\n        p.name, \r\n        p.category, \r\n        p.layer_name, \r\n        p.xp_reward, \r\n        p.checkin_radius,\r\n        p.crowd_level,\r\n        p.has_water,\r\n        p.is_accessible,\r\n        p.alternative_poi_id,\r\n        p.is_recommended,\r\n        ST_Y(p.coords::geometry) as latitude,\r\n        ST_X(p.coords::geometry) as longitude,\r\n        p.p_iva,\r\n        p.image_url,\r\n        p.description\r\n    FROM public.pois p\r\n    WHERE p.is_active = true\r\n    ORDER BY p.name ASC;\r\nEND;\r\n$$ LANGUAGE plpgsql SECURITY DEFINER;\r\n\r\n-- 3. Aggiorniamo get_pois_with_status()\r\nDROP FUNCTION IF EXISTS get_pois_with_status(UUID);\r\n\r\nCREATE OR REPLACE FUNCTION get_pois_with_status(p_profile_id UUID)\r\nRETURNS TABLE (\r\n    id UUID,\r\n    name TEXT,\r\n    category TEXT,\r\n    layer_name TEXT,\r\n    xp_reward INTEGER,\r\n    checkin_radius INTEGER,\r\n    latitude FLOAT8,\r\n    longitude FLOAT8,\r\n    is_visited BOOLEAN,\r\n    crowd_level INTEGER,\r\n    has_water BOOLEAN,\r\n    is_accessible BOOLEAN,\r\n    alternative_poi_id UUID,\r\n    is_recommended BOOLEAN,\r\n    image_url TEXT,\r\n    description TEXT\r\n) AS $$\r\nBEGIN\r\n    RETURN QUERY\r\n    SELECT \r\n        p.id, \r\n        p.name, \r\n        p.category, \r\n        p.layer_name, \r\n        p.xp_reward, \r\n        p.checkin_radius,\r\n        ST_Y(p.coords::geometry) as latitude,\r\n        ST_X(p.coords::geometry) as longitude,\r\n        EXISTS (\r\n            SELECT 1 FROM user_pois up \r\n            WHERE up.poi_id = p.id AND up.profile_id = p_profile_id\r\n        ) as is_visited,\r\n        p.crowd_level,\r\n        p.has_water,\r\n        p.is_accessible,\r\n        p.alternative_poi_id,\r\n        p.is_recommended,\r\n        p.image_url,\r\n        p.description\r\n    FROM public.pois p\r\n    WHERE p.is_active = true;\r\nEND;\r\n$$ LANGUAGE plpgsql SECURITY DEFINER;\r\n\r\n-- 4. Aggiungiamo immagini e descrizioni ai POI esistenti per bellezza UI\r\nUPDATE public.pois SET \r\n    image_url = 'https://lotohub.s3.amazonaws.com/tenants/taranto/castello.jpg',\r\n    description = 'Imponente fortezza marittima che protegge la citta da secoli.'\r\nWHERE name ILIKE '%Castello Aragonese%';\r\n\r\nUPDATE public.pois SET \r\n    image_url = 'https://lotohub.s3.amazonaws.com/tenants/taranto/ipogeo.jpg',\r\n    description = 'Scopri i segreti nascosti sotto le vie della Citta Vecchia.'\r\nWHERE name ILIKE '%Ipogeo%';","content_id":"7b31b241-2da9-4037-9660-b55000b04ce7","schema_version":"1.0"},"visibility":"user","favorite":false,"project":{"id":27102476,"ref":"fsuolbwsvpgiglwcaffh","name":"loto.hub","base_project_id":null},"owner":{"id":10709404,"username":"lototaranto-alt"},"updated_by":{"id":10709404,"username":"lototaranto-alt"},"message":""}
